fn is_greater(n: i32, a: Vec<i32>) -> bool {
    // For each element x in the array, check that n is strictly greater than x.
    // `all` returns true if this holds for every element (and vacuously true on an empty vector).
    a.into_iter().all(|x| n > x)
}

